/* Generated by lozenge. */
#include <stdio.h>
#include <stdlib.h>

static double in0[6];
static double in1[6];
static double t0[4];
static double t1[4];
static double t2[4];
static double t3[8];
static double t4[4];

/* kernel 0: matmul 2x3 by 3x2 */
static void kernel0(void) {
  for (long i = 0; i < 2; i++) {
    for (long j = 0; j < 2; j++) {
      double acc = 0.0;
      for (long l = 0; l < 3; l++) acc += in0[i * 3 + l] * in1[l * 2 + j];
      t0[i * 2 + j] = acc;
    }
  }
}

/* kernel 1: elementwise, 4 elements */
static void kernel1(void) {
  for (long i = 0; i < 4; i++) t1[i] = (t0[i] + (t0[i] * t0[i]));
}

/* kernel 2: transpose 2x2 */
static void kernel2(void) {
  for (long i = 0; i < 2; i++) {
    for (long j = 0; j < 2; j++) t2[j * 2 + i] = t1[i * 2 + j];
  }
}

/* kernel 3: concat 1 blocks of 4 + 4 */
static void kernel3(void) {
  for (long o = 0; o < 1; o++) {
    for (long j = 0; j < 4; j++) t3[o * 8 + j] = t2[o * 4 + j];
    for (long j = 0; j < 4; j++) t3[o * 8 + 4 + j] = t1[o * 4 + j];
  }
}

/* kernel 4: slice 1 blocks of 8, 4 from 2 */
static void kernel4(void) {
  for (long o = 0; o < 1; o++) {
    for (long j = 0; j < 4; j++) t4[o * 4 + j] = t3[o * 8 + 2 + j];
  }
}

static void read_input(double *buf, long n) {
  for (long i = 0; i < n; i++) {
    if (scanf("%lf", &buf[i]) != 1) {
      fprintf(stderr, "lozenge: not enough input numbers\n");
      exit(2);
    }
  }
}

int main(void) {
  read_input(in0, 6);
  read_input(in1, 6);
  kernel0();
  kernel1();
  kernel2();
  kernel3();
  kernel4();
  for (long i = 0; i < 4; i++) printf("%.17g\n", t4[i]);
  return 0;
}
